--
-- Trigger `tb_detail_do`
--
DELIMITER $$
CREATE TRIGGER `trg_tb_detail_do_format_date` BEFORE INSERT ON `tb_detail_do` FOR EACH ROW BEGIN
    IF NEW.tgl_exp REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN
        SET NEW.tgl_exp = DATE_FORMAT(
            STR_TO_DATE(NEW.tgl_exp, '%e/%c/%Y'),
            '%d/%m/%Y'
        );
    END IF;
END
$$
DELIMITER ;

